const PRICING_CONFIG = {
  plans: { basic: 4.99, pro: 9.99, enterprise: 29.99 },
  addons: { 'extra-storage': 2.5, 'priority-support': 5 }
};

export function calculatePrice(plan, addons = []) {
  const basePlanPrice = PRICING_CONFIG.plans[plan] || 0;
  const addonPrice = addons.reduce((total, addon) => total + (PRICING_CONFIG.addons[addon] || 0), 0);
  return Math.round((basePlanPrice + addonPrice) * 100) / 100;
}
